const style=document.createElement('style');style.textContent='.sicoven-modal{position:fixed;inset:0;z-index:99999;background:rgba(3,10,22,.84);display:flex;align-items:center;justify-content:center;padding:2vh 2vw;color:#e5edf8;font:14px/1.45 Segoe UI,Arial,sans-serif}.sicoven-modal[hidden]{display:none}.sic-dialog{width:min(1320px,98vw);height:min(900px,96vh);display:flex;flex-direction:column;background:#0b1424;border:1px solid #263750;border-radius:14px;box-shadow:0 25px 80px #0009;overflow:hidden}.sic-dialog header{display:flex;justify-content:space-between;padding:18px 22px;background:#10213b;border-bottom:1px solid #263750}.sic-dialog h2{margin:3px 0 5px;font-size:23px;color:#fff}.sic-dialog header p{margin:0;color:#9eb0c9}.sic-dialog header small{color:#f4b52c;letter-spacing:.15em;font-weight:800}.sic-close{background:transparent;color:#cbd5e1;border:1px solid #475569;border-radius:8px;font-size:26px;width:38px;height:38px;cursor:pointer}.sic-dialog nav{display:flex;align-items:center;gap:7px;padding:12px 18px;background:#101c2e;flex-wrap:wrap}.sic-dialog nav button,.sic-dialog footer button{background:#17263b;color:#c7d4e6;border:1px solid #33465f;padding:9px 12px;border-radius:7px;cursor:pointer;font-weight:650}.sic-dialog nav button.active{background:#f0b429;color:#182235}.sic-dialog nav button.sic-primary,.sic-primary{background:#176a54;color:#e7fff6;border:1px solid #1f8a6a}.sic-dialog nav span{flex:1}.sic-dialog main{padding:18px 22px;overflow:auto;flex:1}.sic-dialog footer{padding:12px 20px;border-top:1px solid #263750;display:flex;justify-content:space-between;gap:10px;color:#8195b1}.sic-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:12px;margin-bottom:18px}.sic-kpis>div{background:#111f33;border:1px solid #2b3d55;border-radius:9px;padding:13px}.sic-kpis small{display:block;color:#8fa5c1;font-size:11px;margin-bottom:6px}.sic-kpis b{font-size:19px;color:#f5c24c}.sic-table{overflow:auto;border:1px solid #2a3b53;border-radius:9px}.sic-dialog table{width:100%;border-collapse:collapse;min-width:760px}.sic-dialog th,.sic-dialog td{padding:9px 11px;border-bottom:1px solid #24354a;text-align:left;white-space:nowrap}.sic-dialog th{background:#14243a;color:#9db5d3;font-size:11px;position:sticky;top:0}.sic-dialog td{color:#dbe6f5}.sic-dialog .r{text-align:right;font-variant-numeric:tabular-nums}.sic-errors{border:1px solid #854d0e;background:#42200644;border-radius:8px;padding:8px 14px;color:#fde68a}.sic-note{color:#fcd34d;background:#42200644;border:1px solid #854d0e;padding:12px;border-radius:8px}.sic-manual input,.sic-manual select{width:100%;min-width:95px;background:#101f33;border:1px solid #3a4e68;color:#e5edf8;padding:8px;border-radius:6px}.sic-manual h3{margin-top:0}.sic-manual p{color:#9eb0c9}.sic-config{display:grid;grid-template-columns:minmax(120px,1fr) minmax(220px,2fr);gap:10px;align-items:center;margin-bottom:18px}.sic-config label{color:#b7c7dc}.sic-config select{background:#101f33;border:1px solid #3a4e68;color:#e5edf8;padding:9px;border-radius:6px;min-width:0}.sic-primary{padding:10px 15px;border-radius:7px;cursor:pointer;font-weight:700}@media(max-width:650px){.sicoven-modal{padding:0}.sic-dialog{width:100vw;height:100dvh;border-radius:0}.sic-dialog header{padding:14px}.sic-dialog h2{font-size:19px}.sic-dialog main{padding:12px}.sic-dialog footer{flex-direction:column}.sic-config{grid-template-columns:1fr;gap:5px}.sic-dialog nav{padding:8px}.sic-dialog nav button{padding:8px;font-size:12px}}';document.head.appendChild(style);
